-- Дегендерный свип 2026-08 (правило CLAUDE.md «Род читателя: мужских форм
-- быть не должно») доехал до src/bot/healthy-adult.data.ts, но не до пула
-- в БД: канал публикует через HealthyAdultService.pickFromPool, а не из
-- фолбэка, поэтому все правки («Ты вырос» → «Те времена прошли», «Ты лёг»
-- → «а ты», причастия/деепричастия вместо прошедшего времени 2 л. ед.ч. и
-- т.д.) молча не доезжали до читателей. Тот же класс бага, что закрывала
-- 20260728120000_healthy_adult_voice_cleanup для роботных конструкций —
-- здесь тот же механизм для рода.
--
-- Заодно (в этой же ревизии пула, чтобы не плодить миграцию на каждую
-- находку свипа):
--   * убран жаргон без объяснения, запрещённый брифом (HEALTHY_ADULT.md):
--     «режим выживания», «границы» как термин — идентификаторы #11 и #33
--     (по номеру в исходном сиде) переписаны живым языком;
--   * фраза про десятое перечитывание абзаца (#5) — единственная из трёх
--     микросцен на общем ритме «сцена → объяснение → разрешение» на этот
--     раз собрана иначе (реплика вместо сценарной завязки), чтобы три
--     соседние по теме фразы не читались как один шаблон;
--   * из трёх фраз с зачином «Сегодня можно» осталась одна (#15 — приготовить
--     ужин); #18 (дожить до вечера) и #46 (сбавить темп) переоткрыты другой
--     конструкцией.
--
-- Идемпотентно: сверка по точному старому тексту, как и в cleanup-миграции
-- выше. Строку, уже поправленную вручную в админке, UPDATE не тронет —
-- WHERE не найдёт совпадения. "updatedAt" проставляется явно: колонка
-- NOT NULL без DEFAULT (Prisma @updatedAt ставит значение на клиенте) —
-- инцидент 2026-07-16.

UPDATE "HealthyAdultPhrase" SET "text" = 'Третий раз перечитываешь своё сообщение и уже придумываешь, что о тебе подумали. Этому навыку много лет: предугадать чужую реакцию, чтобы успеть подготовиться. Сегодня можно не готовиться.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты перечитал своё сообщение третий раз и уже придумал, что о тебе подумали. Этому навыку много лет: предугадать чужую реакцию, чтобы успеть подготовиться. Сегодня можно не готовиться.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Открываешь ноутбук, смотришь на список дел и закрываешь обратно. Так выглядит перегрузка: пунктов столько, что не за что взяться. Начни с одного, самого маленького.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты открыл ноутбук, посмотрел на список дел и закрыл его обратно. Так выглядит перегрузка: пунктов столько, что не за что взяться. Начни с одного, самого маленького.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Три часа ночи, а ты по кадрам разбираешь разговор десятилетней давности. Мозг не пытается тебя мучить, он пытается доделать то, что тогда осталось без ответа. Ответа там уже нет. Можно закрыть.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты лёг в три ночи и разбирал по кадрам разговор десятилетней давности. Мозг не пытается тебя мучить, он пытается доделать то, что тогда осталось без ответа. Ответа там уже нет. Можно закрыть.';

-- #5: та же микросцена, что и две выше по теме («перечитываешь-открываешь»)
-- — переписана другой структурой (начинается с реплики), не только родом.
UPDATE "HealthyAdultPhrase" SET "text" = '«Опять ничего не понимаю», — мелькает мысль на десятом перечитывании одного и того же абзаца. Голова устала и просит перерыв, а не ещё один заход. Закрой, вернёшься.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты десятый раз перечитываешь один и тот же абзац и ничего не помнишь. Голова устала и просит перерыв, а не ещё один заход. Закрой, вернёшься.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Голос в голове говорит: «соберись, что с тобой не так». Спроси у него: а с тобой стало бы что-то не так, будь ты просто уставшим человеком, а не проектом по улучшению?', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Голос в голове говорит: «соберись, что с тобой не так». Спроси у него: а с тобой стало бы что-то не так, если бы ты был просто уставшим человеком, а не проектом по улучшению?';

UPDATE "HealthyAdultPhrase" SET "text" = 'Критик кричит громко, потому что когда-то это помогало выжить: успеть осудить себя первым, пока не осудили другие. Те времена прошли. Первым можно больше не успевать.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Критик кричит громко, потому что когда-то это помогало выжить: успеть первым назвать себя плохим, пока не назвали другие. Ты вырос. Первым можно больше не успевать.';

-- #11: заодно убран жаргон «режим выживания» (HEALTHY_ADULT.md запрещает
-- терапевтический жаргон без объяснения).
UPDATE "HealthyAdultPhrase" SET "text" = 'Ты называешь это «у меня всё запущено». Посмотри ближе: позади период, в котором сил хватало только на самое важное. Так выглядит истощение, а не лень. Оно пройдёт.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты называешь это «я всё запустил». Посмотри ближе: ты пережил период, в котором сил хватало только на самое важное. У этого есть имя — режим выживания. Он закончится.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Кто-то однажды назвал тебя «слишком чувствительным». Ближе к делу — это способность замечать то, что другие проскакивают. У неё есть цена. Поломки в этом нет.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'То, что зовут «слишком чувствительный», вблизи оказывается способностью замечать то, что другие проскакивают. У этого есть цена. Поломки в этом нет.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Это называют прокрастинацией. Иногда за ней не лень, а тело, которое отказывается делать то, что для него давно перестало иметь смысл. Стоит спросить не «почему я ленюсь», а «почему мне так не хочется именно это».', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты зовёшь это прокрастинацией. Иногда это тело, которое отказывается делать то, что для него давно перестало иметь смысл. Стоит спросить не «почему я ленюсь», а «почему мне так не хочется именно это».';

UPDATE "HealthyAdultPhrase" SET "text" = 'Сегодняшнее разрешение: сделать меньше, чем было в планах, и не открывать по этому поводу заседание трибунала.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Сегодняшнее разрешение: сделать меньше, чем планировал, и не открывать по этому поводу заседание трибунала.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Пауза перед ответом — уважение к себе и к тому, что ты хочешь сказать. Сегодня разрешено ответить не сразу.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Разрешение на день: ответить не сразу. Пауза перед ответом — уважение к себе и к тому, что ты хочешь сказать.';

-- #18: третья из трёх фраз с зачином «Сегодня можно» — переоткрыта другой
-- конструкцией, чтобы зачин не повторялся трижды в одном пуле.
UPDATE "HealthyAdultPhrase" SET "text" = 'Дожить до вечера — это уже программа на сегодня. Не расти, не чинить себя, не становиться лучшей версией. Просто дожить. Этого хватит.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Сегодня можно просто дожить до вечера. Не расти, не чинить себя, не становиться лучшей версией. Просто дожить. Этого хватит.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Каким тоном ты сегодня разговариваешь с собой? Если бы этим тоном с тобой весь день говорил кто-то другой — надолго бы тебя хватило в одной комнате с ним?', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Каким тоном ты сегодня говорил с собой? Если бы этим тоном с тобой весь день говорил кто-то другой, ты бы остался с ним в одной комнате?';

UPDATE "HealthyAdultPhrase" SET "text" = 'Что ты скажешь другу, если он расскажет тебе ровно то, что ты сейчас рассказываешь себе о себе?', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Что бы ты сказал другу, который рассказал бы тебе ровно то, что ты сейчас рассказываешь себе о себе?';

UPDATE "HealthyAdultPhrase" SET "text" = 'Если бы тебе не нужно было это заслужить — хотелось бы этого по-прежнему? Иногда под «надо» лежит настоящее «хочу», а иногда только чужой голос.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Если бы тебе не нужно было это заслужить — ты бы всё равно этого хотел? Иногда под «надо» лежит настоящее «хочу», а иногда только чужой голос.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Посмотри со стороны на человека, который прожил твой день с твоими вводными. Скорее всего, удивишься, как он вообще держится. Этот человек — ты.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Если бы ты со стороны увидел человека, который прожил твой день с твоими вводными, ты бы, скорее всего, удивился, как он вообще держится. Этот человек — ты.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Представь, что за сегодня отвечаешь не ты, а кто-то, кого ты любишь. И с него ты будешь требовать то, что требуешь с себя? Тогда почему с собой можно жёстче.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Представь, что за сегодня отвечал не ты, а кто-то, кого ты любишь. Ты бы стал требовать с него того, что требуешь с себя? Тогда почему с собой можно жёстче.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Есть в тебе кто-то маленький, кто всё ещё ждёт, что любовь надо сначала заслужить удобством. Порядок можно поменять. Сначала ты, а удобство — как получится.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Есть в тебе кто-то маленький, кто всё ещё ждёт, что сначала надо стать удобным, а потом полюбят. Порядок можно поменять. Сначала ты, а удобство — как получится.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Отдых не выдают за заслуги. Он нужен просто потому, что ты человек.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Отдых не выдают за заслуги. Он нужен просто потому, что ты живой.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Чтобы иметь право на бережность, не нужно быть в форме.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты не обязан быть в форме, чтобы иметь право на бережность.';

