-- (HEALTHY_ADULT.md).
UPDATE "HealthyAdultPhrase" SET "text" = 'Где заканчиваешься ты и начинается другой человек — стоит замечать, не только чувствовать.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Границы отмечают, где заканчиваешься ты и начинается другой.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Пара плохих дней подряд ощущается как крах. Но позади есть куда больше хороших дней — они не исчезли, просто сейчас не на виду. Такие полосы уже бывали и заканчивались — закончится и эта.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Пара плохих дней подряд не перечёркивает всё, что было до. Такие уже бывали и проходили — пройдут и эти.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Вернуться к чему-то после долгого перерыва — это смелость: начать заново там, где когда-то не получилось.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Если ты вернулся к чему-то после долгого перерыва — это смелость: начать заново там, где когда-то не получилось.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Вокруг может быть полно людей, а одиноко — потому что рядом нет того, с кем можно не притворяться. Стоит заметить это, а не списать на себя.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Иногда одиночество — про то, что рядом нет того, кому можно не притворяться. Людей при этом может быть полно. Стоит заметить это, а не списать на себя.';

UPDATE "HealthyAdultPhrase" SET "text" = 'Смелость не ждёт, пока пройдёт страх. Она выглядит так: страшно — и всё равно делаешь маленький шаг.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Ты не обязан быть спокойным, чтобы начать. Смелость выглядит так: страшно — и всё равно делаешь маленький шаг.';

-- #46: последняя из трёх фраз с зачином «Сегодня можно» — переоткрыта, в
